const examples = [
  { syllables: ['ῥί', 'ζα'], note: 'The opening example in the list.' },
  { syllables: ['δό', 'ξα'], note: 'The list gives this before the city Φρίξα.' },
  { syllables: ['δί', 'ψα'], note: 'The list gives this before the city Κάψα.' },
  { syllables: ['ὄ', 'ρυ', 'ζα'], note: 'Herodian gives this first after stating the rule for longer words.' },
  { syllables: ['τρά', 'πε', 'ζα'], note: 'Herodian also gives this as the name of a city in Arcadia near Tricoloni.' },
  { syllables: ['ἀρ', 'γυ', 'ρό', 'πε', 'ζα'], note: 'Here the third syllable from the end is the middle syllable.' },
  { syllables: ['τε', 'τρά', 'πε', 'ζα'], note: 'Here the acute falls on the second of four syllables.' },
  { syllables: ['Δού', 'ρι', 'ζα'], note: 'A lake by the river Λίζας, cited from Hecataeus’s Circuit of Asia.' },
  { syllables: ['Φρί', 'ξα'], note: 'The passage places this city in Triphylia. Pherecydes places it in Arcadia.' },
  { syllables: ['Δά', 'ρα', 'ψα'], note: 'A city in Bactria according to Strabo.' },
  { syllables: ['Βαί', 'σαμ', 'ψα'], note: 'A city near the Red Sea whose name is glossed as “house of the sun.”' }
];

const positionNames = ['ultima', 'penult', 'antepenult'];
const input = document.querySelector('#word');
const prompt = document.querySelector('#prompt');
const details = document.querySelector('#details');
const syllables = document.querySelector('#syllables');
const position = document.querySelector('#position');
const note = document.querySelector('#note');
const exampleList = document.querySelector('#examples');

function lookupKey(word) {
  return word.trim().normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
}

function showExample() {
  const key = lookupKey(input.value);
  const example = examples.find(({ syllables }) => lookupKey(syllables.join('')) === key);
  details.hidden = !example;
  prompt.hidden = Boolean(example);

  if (!example) {
    syllables.replaceChildren();
    position.textContent = '';
    note.textContent = '';
    prompt.textContent = key
      ? 'This word is outside the example list. Try one of the choices above.'
      : 'Choose a Greek example to begin.';
    return;
  }

  const index = example.syllables.findIndex(part => part.normalize('NFD').includes('\u0301'));
  syllables.replaceChildren();
  example.syllables.forEach((part, i) => {
    if (i) syllables.append(' · ');
    if (i === index) {
      const accented = document.createElement('mark');
      accented.textContent = part;
      syllables.append(accented);
    } else {
      syllables.append(part);
    }
  });
  const count = example.syllables.length;
  const fromEnd = count - index;
  const names = ['last', 'second from the end', 'third from the end'];
  position.textContent = `${count} syllables · Acute on the ${positionNames[fromEnd - 1]} (${names[fromEnd - 1]})`;
  note.textContent = example.note;
}

for (const { syllables: parts } of examples) {
  const word = parts.join('');
  const item = document.createElement('li');
  const button = document.createElement('button');
  button.type = 'button';
  button.lang = 'el';
  button.textContent = word;
  button.addEventListener('click', () => {
    input.value = word;
    showExample();
  });
  item.append(button);
  exampleList.append(item);
}
document.querySelector('#check').addEventListener('click', showExample);
document.querySelector('#clear').addEventListener('click', () => {
  input.value = '';
  showExample();
  input.focus();
});
input.addEventListener('keydown', event => {
  if (event.key === 'Enter' && !event.isComposing) showExample();
});

