const find = selector => document.querySelector(selector);
const input = find('#inp');
const kinds = Array.from(document.querySelectorAll('input[name="kind"]'));
const endings = ['αιος', 'αυος', 'οιος'];
const vowels = 'αεηιουω';
const diphthongs = new Set(['αι', 'αυ', 'ει', 'ευ', 'ηυ', 'οι', 'ου', 'υι', 'ωυ']);
const properAios = new Set(['σκαιος', 'βαιος', 'γραιος', 'παιος']);
const citedOios = new Set(['ποιος', 'τοιος', 'κοιος', 'οιος']);

function base(letter) {
  return letter[0].toLowerCase();
}

function isDiphthong(first, second) {
  return second && !/[\u0313\u0314]/.test(first) && !second.includes('\u0308')
    && diphthongs.has(base(first) + base(second));
}

function readWord(word) {
  const letters = word.normalize('NFD').match(/\p{Script=Greek}\p{M}*/gu) || [];
  if (letters.length === 0 || letters.join('') !== word.normalize('NFD')) return null;

  const key = letters.map(base).join('').replace(/σ$/, 'ς');
  let syllables = 0;
  for (let i = 0; i < letters.length; i += 1) {
    if (!vowels.includes(base(letters[i]))) continue;
    syllables += 1;
    if (isDiphthong(letters[i], letters[i + 1])) i += 1;
  }

  const ending = endings.find(item => key.endsWith(item));
  return { word, letters, key, ending, syllables };
}

function addAccent(entry, mark) {
  const { letters, key } = entry;
  const marked = letters.map(letter => letter.replace(/[\u0300\u0301\u0342]/g, ''));
  const index = mark === 'acute' ? marked.length - 2 : marked.length - 3;

  if (!/[\u0313\u0314]/.test(marked.join(''))) {
    if (key === 'αυος') marked[index] += /\p{Lu}/u.test(marked[0]) ? '\u0313' : '\u0314';
    if (key === 'οιος') marked[index] += '\u0314';
  }

  marked[index] += mark === 'acute' ? '\u0301' : '\u0342';
  return marked.join('').replace(/σ$/, 'ς').normalize('NFC');
}

function suggest(entry, kind) {
  if (!entry) return { note: 'Enter one Greek word.' };

  const { letters, key, ending, syllables } = entry;
  if (!ending) return { note: 'The examples here end in -αιος, -αυος or -οιος.' };
  if (key === 'αγαυος') return { note: 'Herodian singles out ἀγαυός as trisyllabic.' };
  if (syllables !== 2 || !isDiphthong(letters.at(-4), letters.at(-3))) {
    return { note: 'This suggestion needs two syllables and a diphthong in the ending.' };
  }
  if (ending === 'αυος') {
    return { mark: 'circumflex', note: 'Herodian gives ναῦος and αὗος with a circumflex on the first syllable.' };
  }
  if (ending === 'οιος' && citedOios.has(key)) {
    return { mark: 'circumflex', note: 'Herodian lists ποῖος, τοῖος, κοῖος and οἷος with a circumflex on the first syllable.' };
  }
  const citedName = ending === 'αιος' && properAios.has(key);
  const writtenAsName = citedName && /^\p{Lu}/u.test(entry.word) && letters.at(-3).includes('\u0342');
  if (kind === 'proper' || (kind === 'auto' && writtenAsName)) {
    if (citedName) {
      return { mark: 'circumflex', note: 'Herodian records Σκαῖος, Βαῖος, Γραῖος and Παῖος as proper names.' };
    }
    return { note: 'Herodian exempts proper names from the usual rule for this ending.' };
  }
  if (ending === 'οιος' && kind === 'interrog') {
    return { note: 'Try the cited exceptions ποῖος, τοῖος, κοῖος and οἷος.' };
  }
  return { mark: 'acute', note: 'The usual rule puts an acute on the final syllable.' };
}

function comparison(entry, ending, kind) {
  if (!entry?.ending || entry.syllables !== 2) return '—';
  if (entry.ending === ending) {
    const { mark } = suggest(entry, kind);
    return mark ? addAccent(entry, mark) : '—';
  }
  const originalEnding = entry.letters.slice(-4);
  const changed = Array.from(ending, (letter, index) =>
    /\p{Lu}/u.test(originalEnding[index]) ? letter.toUpperCase() : letter
  );
  const form = readWord(entry.letters.slice(0, -4).concat(changed).join(''));
  const { mark } = suggest(form, kind);
  return mark ? addAccent(form, mark) : '—';
}

function render() {
  const word = input.value.trim().normalize('NFC');
  const kind = kinds.find(control => control.checked).value;
  const entry = readWord(word);
  const { mark, note } = suggest(entry, kind);

  find('#outWord').textContent = mark ? addAccent(entry, mark) : (word || '—');
  find('#outMeta').textContent = word ? note : 'Enter a word to see a suggested accent and rule.';
  find('#detEnd').textContent = entry?.ending ? '-' + entry.ending : '—';
  find('#detSyl').textContent = entry?.syllables || '—';
  const labels = { acute: 'Acute on the final syllable', circumflex: 'Circumflex on the first syllable' };
  find('#detAcc').textContent = labels[mark] || '—';
  ['#cmpAios', '#cmpAuos', '#cmpOios'].forEach((selector, index) => {
    find(selector).textContent = comparison(entry, endings[index], kind);
  });
}

find('#btn').addEventListener('click', render);
find('#btnClear').addEventListener('click', () => {
  input.value = '';
  kinds[0].checked = true;
  render();
  input.focus();
});
input.addEventListener('input', render);
input.addEventListener('keydown', event => {
  if (event.key === 'Enter' && !event.isComposing) render();
});
document.querySelectorAll('.chip').forEach(chip => chip.addEventListener('click', () => {
  input.value = chip.dataset.w;
  kinds.find(control => control.value === (chip.dataset.kind || 'auto')).checked = true;
  render();
  input.focus();
}));
kinds.forEach(control => control.addEventListener('change', render));
render();

